// Regenerates src/lessons/registry.ts from the L####.tsx files present.
import { readdirSync, writeFileSync } from 'node:fs';

const dir = new URL('../src/lessons/', import.meta.url);
const files = readdirSync(dir)
  .filter((f) => /^L\d{4}\.tsx$/.test(f))
  .sort();
const lines = [
  '// AUTO-GENERATED by scripts/gen-registry.mjs. Do not edit.',
  "import type { LessonVisuals } from '../kit';",
  ...files.map((f) => `import ${f.replace('.tsx', '')} from './${f.replace('.tsx', '')}';`),
  '',
  'export const registry: Record<number, LessonVisuals> = {',
  ...files.map((f) => `  ${Number(f.slice(1, 5))}: ${f.replace('.tsx', '')},`),
  '};',
  '',
];
writeFileSync(new URL('registry.ts', dir), lines.join('\n'));
console.log(`registry: ${files.length} lesson(s)`);
